import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { test } from 'node:test'
import { createMiniApp, validateInitData } from '../telegram-miniapp.js'

// Independent published Telegram Mini Apps vector (docs.telegram-mini-apps.com):
// bot token and initData are fixed; the signature is not generated by this test.
const VECTOR_TOKEN = '5768337691:AAH5YkoiEuPk8-FZa32hStHTqXiLPtAEhx8'
const VECTOR_DATA = 'query_id=AAHdF6IQAAAAAN0XohDhrOrc&user=%7B%22id%22%3A279058397%2C%22first_name%22%3A%22Vladislav%22%2C%22last_name%22%3A%22Kibenko%22%2C%22username%22%3A%22vdkfrost%22%2C%22language_code%22%3A%22ru%22%2C%22is_premium%22%3Atrue%7D&auth_date=1662771648&hash=c501b71e775f74ce10e377dea85a7ea24ecd640b223ea86dfe453e0eaed2e2b2'
const VECTOR_NOW = 1662771648000
const VECTOR_USER = 279058397

function serve(handler) {
  return new Promise((resolve) => {
    const server = createServer((req, res) => Promise.resolve(handler(req, res)).catch((error) => { res.writeHead(500); res.end(String(error)) }))
    server.listen(0, '127.0.0.1', () => resolve({ server, base: `http://127.0.0.1:${server.address().port}` }))
  })
}

test('published Telegram initData vector validates; tamper and expiry fail', () => {
  const valid = validateInitData(VECTOR_DATA, VECTOR_TOKEN, { now: VECTOR_NOW })
  assert.equal(valid.user.id, VECTOR_USER)
  const tampered = VECTOR_DATA.replace(/hash=[0-9a-f]{64}/, `hash=${'0'.repeat(64)}`)
  assert.equal(validateInitData(tampered, VECTOR_TOKEN, { now: VECTOR_NOW }), null)
  assert.equal(validateInitData(VECTOR_DATA, VECTOR_TOKEN, { now: VECTOR_NOW + 90_000_000 }), null)
})

test('Mini App auth uses the header, binds user to allowlist, is read-only and rate-limited', async (t) => {
  const runtime = { sessionId: 'agent-1', model: null, agent: { status: 'idle' }, pulseHistory: [] }
  const staticDir = new URL('../telegram-miniapp/', import.meta.url).pathname
  const app = createMiniApp({ runtime, botToken: VECTOR_TOKEN, allowedUserIds: [VECTOR_USER], staticDir, dataDir: '/tmp/none', rateLimit: 2, now: VECTOR_NOW })
  const { server, base } = await serve(app)
  t.after(() => new Promise((resolve) => server.close(resolve)))
  const auth = { 'x-telegram-init-data': VECTOR_DATA }

  assert.equal((await fetch(`${base}/telegram-miniapp/`)).status, 200, 'static shell is unauthenticated')
  assert.equal((await fetch(`${base}/telegram-miniapp/api/status`)).status, 401)
  assert.equal((await fetch(`${base}/telegram-miniapp/api/status?initData=${encodeURIComponent(VECTOR_DATA)}`)).status, 401, 'query auth is not accepted')
  assert.equal((await fetch(`${base}/telegram-miniapp/api/status`, { headers: auth })).status, 200)
  const forbidden = createMiniApp({ runtime, botToken: VECTOR_TOKEN, allowedUserIds: [42], staticDir, dataDir: '/tmp/none', rateLimit: 100, now: VECTOR_NOW })
  const other = await serve(forbidden)
  t.after(() => new Promise((resolve) => other.server.close(resolve)))
  assert.equal((await fetch(`${other.base}/telegram-miniapp/api/status`, { headers: auth })).status, 403)
})

test('read-only rejects POST and rate limit is keyed by authenticated user', async (t) => {
  const runtime = { sessionId: 'a', model: null, agent: { status: 'idle' }, pulseHistory: [] }
  const staticDir = new URL('../telegram-miniapp/', import.meta.url).pathname
  const app = createMiniApp({ runtime, botToken: VECTOR_TOKEN, allowedUserIds: [VECTOR_USER], staticDir, dataDir: '/tmp/none', rateLimit: 100, now: VECTOR_NOW })
  const { server, base } = await serve(app)
  t.after(() => new Promise((resolve) => server.close(resolve)))
  const auth = { 'x-telegram-init-data': VECTOR_DATA }
  const post = await fetch(`${base}/telegram-miniapp/api/status`, { method: 'POST', headers: auth })
  assert.equal(post.status, 405)
  assert.equal(post.headers.get('allow'), 'GET')
  const limited = createMiniApp({ runtime, botToken: VECTOR_TOKEN, allowedUserIds: [VECTOR_USER], staticDir, dataDir: '/tmp/none', rateLimit: 1, now: VECTOR_NOW })
  const small = await serve(limited)
  t.after(() => new Promise((resolve) => small.server.close(resolve)))
  assert.equal((await fetch(`${small.base}/telegram-miniapp/api/status`, { headers: auth })).status, 200)
  assert.equal((await fetch(`${small.base}/telegram-miniapp/api/status`, { headers: auth })).status, 429)
})

test('pulses cap at 50 and CSP allows the Telegram Web origin', async (t) => {
  const runtime = { sessionId: 'a', model: null, agent: { status: 'idle' }, pulseHistory: Array.from({ length: 60 }, (_, i) => ({ kind: 'pulse', title: `p${i}` })) }
  const staticDir = new URL('../telegram-miniapp/', import.meta.url).pathname
  const app = createMiniApp({ runtime, botToken: VECTOR_TOKEN, allowedUserIds: [VECTOR_USER], staticDir, dataDir: '/tmp/none', rateLimit: 100, now: VECTOR_NOW })
  const { server, base } = await serve(app)
  t.after(() => new Promise((resolve) => server.close(resolve)))
  const auth = { 'x-telegram-init-data': VECTOR_DATA }
  const response = await fetch(`${base}/telegram-miniapp/api/pulses`, { headers: auth })
  const body = await response.json()
  assert.equal(body.pulses.length, 50)
  const shell = await fetch(`${base}/telegram-miniapp/`)
  assert.match(shell.headers.get('content-security-policy'), /frame-ancestors https:\/\/web\.telegram\.org/)
  assert.equal(shell.headers.get('x-frame-options'), null, 'CSP frame-ancestors is the framing control')
})
